class Solution {
    public TreeNode constructMaximumBinaryTree(int[] nums) {
        return build(nums, 0, nums.length - 1);
    }

    private TreeNode build(int[] nums, int left, int right) {
        if (left > right) {
            return null;
        }
        int maxIndex = left;
        for (int i = left + 1; i <= right; i++) {
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }

        TreeNode root = new TreeNode(nums[maxIndex]);
        root.left = build(nums, left, maxIndex - 1);
        root.right = build(nums, maxIndex + 1, right);
        return root;
    }
}

class Solution {
    public TreeNode constructMaximumBinaryTree(int[] nums) {
        java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>();

        for (int value : nums) {
            TreeNode node = new TreeNode(value);
            while (!stack.isEmpty() && stack.peek().val < value) {
                node.left = stack.pop();
            }
            if (!stack.isEmpty()) {
                stack.peek().right = node;
            }
            stack.push(node);
        }

        TreeNode root = null;
        while (!stack.isEmpty()) {
            root = stack.pop();
        }
        return root;
    }
}

class Solution {
    private int[] nums;
    private int[] tree;

    public TreeNode constructMaximumBinaryTree(int[] nums) {
        this.nums = nums;
        this.tree = new int[nums.length * 4];
        buildIndexTree(1, 0, nums.length - 1);
        return buildTree(0, nums.length - 1);
    }

    private void buildIndexTree(int node, int left, int right) {
        if (left == right) {
            tree[node] = left;
            return;
        }
        int mid = (left + right) >>> 1;
        buildIndexTree(node * 2, left, mid);
        buildIndexTree(node * 2 + 1, mid + 1, right);
        tree[node] = better(tree[node * 2], tree[node * 2 + 1]);
    }

    private TreeNode buildTree(int left, int right) {
        if (left > right) {
            return null;
        }
        int maxIndex = query(1, 0, nums.length - 1, left, right);
        TreeNode root = new TreeNode(nums[maxIndex]);
        root.left = buildTree(left, maxIndex - 1);
        root.right = buildTree(maxIndex + 1, right);
        return root;
    }

    private int query(int node, int left, int right, int queryLeft, int queryRight) {
        if (queryLeft <= left && right <= queryRight) {
            return tree[node];
        }
        int mid = (left + right) >>> 1;
        if (queryRight <= mid) {
            return query(node * 2, left, mid, queryLeft, queryRight);
        }
        if (queryLeft > mid) {
            return query(node * 2 + 1, mid + 1, right, queryLeft, queryRight);
        }
        return better(
                query(node * 2, left, mid, queryLeft, queryRight),
                query(node * 2 + 1, mid + 1, right, queryLeft, queryRight));
    }

    private int better(int first, int second) {
        return nums[first] >= nums[second] ? first : second;
    }
}

class Solution {
    private int[] nums;
    private int[] logs;
    private int[][] table;

    public TreeNode constructMaximumBinaryTree(int[] nums) {
        this.nums = nums;
        buildSparseTable(nums);
        return build(0, nums.length - 1);
    }

    private void buildSparseTable(int[] nums) {
        int n = nums.length;
        logs = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            logs[i] = logs[i / 2] + 1;
        }

        int levels = logs[n] + 1;
        table = new int[levels][n];
        for (int i = 0; i < n; i++) {
            table[0][i] = i;
        }
        for (int level = 1; level < levels; level++) {
            int half = 1 << (level - 1);
            int length = 1 << level;
            for (int start = 0; start + length <= n; start++) {
                table[level][start] = better(table[level - 1][start], table[level - 1][start + half]);
            }
        }
    }

    private TreeNode build(int left, int right) {
        if (left > right) {
            return null;
        }
        int maxIndex = queryMaxIndex(left, right);
        TreeNode root = new TreeNode(nums[maxIndex]);
        root.left = build(left, maxIndex - 1);
        root.right = build(maxIndex + 1, right);
        return root;
    }

    private int queryMaxIndex(int left, int right) {
        int length = right - left + 1;
        int level = logs[length];
        int span = 1 << level;
        return better(table[level][left], table[level][right - span + 1]);
    }

    private int better(int first, int second) {
        return nums[first] >= nums[second] ? first : second;
    }
}
